-- Брендбук: то, чем пользуются в работе каждый день.
--
-- Примеры тона выведены из записи «Редакционная политика» базы знаний.
-- Контакты — только проверенные: то, что стоит в рабочих конфигурациях
-- и на сайте. Пустые места оставлены пустыми намеренно.

insert into public.brand (id, title, kind, sort, data) values

('voice-examples', 'Тон голоса: так и не так', 'text', 95, jsonb_build_object('body',
  E'Правила тона легко кивнуть и забыть. Примеры работают лучше. Черновик — поправьте под себя.\n\n— Не так: «Инновационные решения для комплексного продвижения вашего бренда». Так: «Снимаем ролики, делаем айдентику и сайты. Всё по одному договору».\n— Не так: «Мы №1 на рынке Перми». Так: «Работаем с 2018 года, делаем видео, дизайн, фото и ИИ-контент».\n— Не так: «Успейте! Осталось 3 места!». Так: «На октябрь остались две съёмочные смены».\n— Не так: «Клиент был в восторге от результата». Так: «Ролик показали на выставке, заказчик вернулся за второй серией».\n— Не так: «Конкуренты снимают плохо». Так: «Мы считаем, что ролик начинается со сценария, а не с камеры».\n— Не так: «Наша команда профессионалов». Так: «Ведём проекты сами, под задачу привлекаем профильных специалистов».')),

('contacts', 'Контакты и адреса', 'text', 130, jsonb_build_object('body',
  E'То, что указывается в макетах, подписях и документах. Проверьте и дополните — часть данных ещё не внесена.\n\n— Сайт студии: adervis.ru\n— Adervis CRM: app.adervis.ru\n— Adervis Stock: stock.adervis.ru\n— Почта: adervis.digital@gmail.com\n— Телеграм для клиентов Stock: @adervis_manager\n— Телефон: не внесён\n— Юридические реквизиты: не внесены\n— Адрес для встреч: не внесён')),

('handoff', 'Перед тем как отдать макет', 'text', 135, jsonb_build_object('body',
  E'Короткая проверка, которая ловит почти все ошибки фирменного стиля.\n\n— Логотип взят из файла, не перерисован и не растянут\n— Знак на тёмном фоне; на светлом — только версия с тёмным текстом\n— Цвета взяты из палитры, а не подобраны на глаз\n— Заголовки Eurostile Extd, текст TT Fors; если шрифтов нет — Unbounded и Golos Text\n— Отступы кратны четырём\n— Контраст текста к фону не ниже 7:1\n— Название написано верно: ADERVIS, Adervis CRM, Adervis Stock\n— В тексте нет непроверенных цифр'))

on conflict (id) do nothing;
